create type hypothesis_status as enum ('PROPOSED','TESTING','SUPPORTED','REFUTED','INCONCLUSIVE');
create type thesis_status as enum ('EXPLORING','ACTIVE','STRENGTHENING','WEAKENING','CONFLICTED','BROKEN','CLOSED');
create type condition_type as enum ('REQUIRED','KILL');
create table hypotheses (id uuid primary key default gen_random_uuid(), statement text not null, status hypothesis_status not null, entity_ids uuid[] not null default '{}', theme_ids uuid[] not null default '{}', supporting_claim_ids uuid[] not null default '{}', contradicting_claim_ids uuid[] not null default '{}', confidence numeric check (confidence between 0 and 1), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table theses (id uuid primary key default gen_random_uuid(), title text not null, company_id uuid references entities(id), status thesis_status not null, current_revision_id uuid, confidence numeric not null check (confidence between 0 and 1), variant_perception text, hypothesis_ids uuid[] not null default '{}', question_ids uuid[] not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table thesis_revisions (id uuid primary key default gen_random_uuid(), thesis_id uuid not null references theses(id), revision_number integer not null, summary text not null, confidence numeric not null check (confidence between 0 and 1), status thesis_status not null, evidence_ids uuid[] not null default '{}', hypothesis_ids uuid[] not null default '{}', question_ids uuid[] not null default '{}', change_summary text not null, created_at timestamptz not null default now(), unique(thesis_id, revision_number));
alter table theses add constraint theses_current_revision_fk foreign key (current_revision_id) references thesis_revisions(id) deferrable initially deferred;
create table thesis_conditions (id uuid primary key default gen_random_uuid(), thesis_id uuid not null references theses(id), type condition_type not null, statement text not null, status text not null default 'OPEN', evidence_ids uuid[] not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table risks (id uuid primary key default gen_random_uuid(), thesis_id uuid not null references theses(id), statement text not null, likelihood numeric not null check (likelihood between 0 and 1), impact numeric not null check (impact between 0 and 1), evidence_ids uuid[] not null default '{}', created_at timestamptz not null default now());
create table catalysts (id uuid primary key default gen_random_uuid(), thesis_id uuid not null references theses(id), statement text not null, expected_at timestamptz, evidence_ids uuid[] not null default '{}', created_at timestamptz not null default now());
create table forecasts (id uuid primary key default gen_random_uuid(), thesis_id uuid not null references theses(id), metric text not null, period text not null, value numeric not null, unit text not null, assumptions text[] not null default '{}', created_at timestamptz not null default now());
create table contradictions (id uuid primary key default gen_random_uuid(), thesis_id uuid references theses(id), claim_a_id uuid not null references claims(id), claim_b_id uuid not null references claims(id), description text not null, status text not null default 'OPEN', created_at timestamptz not null default now());
